"""Reproducible demo data. Hand-authored text and simulated monthly histories.
No personal financial records are included. Splits are explicit, not duplicated.
"""
import csv, json, random
from pathlib import Path
root = Path(__file__).resolve().parents[1] / 'ML' / 'Data'
root.mkdir(parents=True, exist_ok=True)
training = {
'Groceries': ['Keells supermarket weekly groceries','Cargills Food City food shopping','Arpico grocery basket','rice dhal and coconut oil','fresh milk and eggs','vegetables from local market','fruit bananas and apples','bread from bakery for breakfast','Ceylon tea and sugar','fish from fish market','chicken and meat for cooking','potatoes carrots and onions','flour and baking ingredients','yoghurt and cheese','pasta and noodles','spices salt and pepper','breakfast cereal and oats','bottled drinking water groceries','frozen vegetables and peas','biscuits and crackers','tinned tuna and beans','weekly pantry restock','butter and cooking oil','green leaves from vegetable stall','baby food and milk powder','coffee beans and cocoa','red rice and lentils','grocery delivery from supermarket','dairy products and curd','fresh produce for family meals'],
'Utilities': ['CEB electricity bill','LECO monthly power payment','National Water Board bill','Dialog home broadband subscription','SLT fibre internet monthly rental','Mobitel mobile phone bill','Lanka Bell telephone charges','domestic gas cylinder refill','household utility payment','electric meter standing charge','water supply monthly invoice','home internet data package','prepaid phone recharge','electricity usage for apartment','landline telephone rental','broadband router connection fee','sewerage service bill','municipal waste collection fee','cooking gas delivery','electric power late payment','Dialog television subscription','Peo TV monthly fee','renewal of home WiFi plan','Hutch mobile data top up','NWSDB water invoice','monthly satellite television service','home telephone call charges','utility service connection deposit','gas cylinder for household cooking','internet installation service'],
'Transport': ['petrol for family car','diesel fuel at filling station','PickMe taxi ride home','Uber trip to office','bus fare to Colombo','train ticket to Kandy','tuk tuk fare to market','expressway toll payment','parking fee at shopping mall','vehicle service and engine oil','car insurance renewal','motorcycle tyre replacement','car repair at garage','annual vehicle revenue licence','emission test for vehicle','school van transport fee','monthly bus season pass','airport taxi transfer','wheel alignment and balancing','car battery replacement','motorbike petrol refill','train season ticket','paid parking at hospital','car wash and vehicle cleaning','three wheeler transport charge','highway toll for family trip','brake pads for car','vehicle air filter replacement','taxi booking charge','public transport card top up'],
'Home': ['monthly house rent','apartment rental payment','plumber repaired kitchen tap','electrician fixed ceiling light','AC maintenance and cleaning','washing machine repair','new sofa for living room','bedroom furniture purchase','garden maintenance service','roof leak repair','paint for bedroom walls','mop and floor cleaner','laundry detergent and dish soap','home cleaning service','pest control treatment','replacement light bulbs','door lock and house keys','curtains for living room','kitchen utensils and plates','mattress and pillows','bathroom shower repair','carpenter fixed wardrobe','refrigerator servicing','garden plants and compost','gutter cleaning before rain','home appliance spare parts','housing association maintenance fee','tiles and cement for home repair','new broom and dustpan','water pump repair for house'],
'Health': ['pharmacy medicine purchase','doctor consultation fee','hospital medical bill','dental checkup and cleaning','blood test laboratory fee','prescription tablets and antibiotics','vitamins from pharmacy','eye test at optician','physiotherapy treatment session','health insurance premium','medical scan and X ray','vaccination at clinic','specialist channeling appointment','asthma inhaler refill','diabetes medicine refill','dental filling at dentist','spectacles and prescription lenses','surgical dressing and bandages','child pediatric consultation','clinic registration and treatment','pain relief medicine','allergy medication at pharmacy','medical equipment thermometer','hospital admission fee','routine health screening','first aid kit for home','doctor prescribed cough syrup','eye drops from chemist','cardiology consultation','laboratory urine test'],
'Other': ['cinema tickets for family','birthday gift for cousin','restaurant dinner with family','school tuition class fees','books and stationery','clothes and shoes shopping','charity donation','museum entry tickets','haircut at salon','streaming music membership','hotel stay for holiday','gym membership fee','pet food for dog','veterinary visit for cat','university examination fee','birthday cake for celebration','sports club subscription','travel suitcase purchase','bank account service fee','postage and courier parcel','mobile phone handset purchase','laptop accessories and charger','art supplies and craft paper','concert tickets','kids toys and board game','wedding present','online course registration','swimming lesson fees','photo printing service','passport application fee']}
validation = {
'Groceries':['Fresh eggs and bread from Keells','Market vegetables for cooking','Weekly rice and dhal shopping','Supermarket fruit and dairy','Ceylon tea bags for pantry','Milk powder and breakfast oats'],
'Utilities':['CEB monthly household power usage','SLT broadband data bill','Water supply payment to NWSDB','Dialog mobile monthly charges','Refill cylinder with cooking gas','Pay home television subscription'],
'Transport':['Uber taxi home from work','Diesel purchase for van','Bus ticket for morning commute','Replace car engine oil','Expressway toll charge','Parking at railway station'],
'Home':['Repair leaking roof at house','Buy new curtains for bedroom','Pay apartment rent for June','Kitchen sink plumber charge','Deep cleaning the living room','AC service for master bedroom'],
'Health':['Blood sugar laboratory check','Dental clinic consultation','Collect tablets at pharmacy','Hospital ultrasound scan fee','Prescription lenses from optician','Clinic vaccination appointment'],
'Other':['Buy concert passes','Donation to local charity','New school stationery','Family meal at restaurant','Birthday present for sister','Haircut and salon visit']}
testing = {
'Groceries':['Keells receipt for milk and bread','Food City weekly pantry items','Apples bananas and yoghurt for breakfast','Rice lentils and spices for dinner','Fresh chicken from market','Sugar coffee and tea restock','Grocery shopping at Arpico','Vegetable stall fresh tomatoes and onions','Canned beans pasta and flour','Cheese butter and eggs'],
'Utilities':['Pay CEB bill for electricity','Water Board monthly water charge','Dialog fibre home broadband payment','SLT internet monthly subscription renewal','LECO power supply invoice','Mobitel recharge for phone calls','Home cooking gas refill payment','Television subscription for this month','NWSDB utility water service','Monthly home WiFi data bill'],
'Transport':['PickMe fare to the office','Petrol purchase for motorcycle','Train ride tickets for weekend','Car garage brake repair','Annual motor vehicle insurance','Highway expressway toll fee','Uber taxi fare to airport','Bus season ticket renewal','New tyres for family car','Mall car parking charge'],
'Home':['AC filter cleaning and service','Monthly rental for family apartment','Purchase bedroom wardrobe furniture','Plumber visit for leaking tap','Living room paint and curtains','Roof and gutter maintenance','Buy floor mop and laundry detergent','Fridge repair technician payment','Gardener trimming plants','Replacement lock for front door'],
'Health':['Medicine and vitamins at pharmacy','Doctor appointment for child','Dentist bill for tooth filling','Medical blood test at hospital','Monthly health insurance payment','Physiotherapy clinic treatment','Prescription asthma inhaler','Optician eye examination','Buy bandages and thermometer','Specialist consultation at medical centre'],
'Other':['Movie tickets for Saturday night','Gift for a friends wedding','Annual gym subscription','Lunch with family at restaurant','School books and pencils','New pair of shoes','Donate to charity fundraiser','Pet vet appointment','Music streaming renewal','Laptop charger replacement']}
for split, groups in [('train',training),('validation',validation),('test',testing)]:
 rows=[dict(text=text,category=category) for category, texts in groups.items() for text in texts]
 with (root/f'categories-{split}.csv').open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=['text','category']); writer.writeheader(); writer.writerows(rows)
 (root/f'categories-{split}.json').write_text(json.dumps(rows,indent=2))
all_sets=[set(t.lower().strip() for texts in g.values() for t in texts) for g in [training,validation,testing]]
assert not(all_sets[0]&all_sets[1] or all_sets[0]&all_sets[2] or all_sets[1]&all_sets[2])
# Each split simulates different households. Monthly windows remain within a split.
# Ratios make the model independent of the user's currency/absolute spending level.
for split,count,seed in [('train',1600,71),('validation',320,72),('test',320,73)]:
 rng=random.Random(seed);rows=[]
 for _ in range(count):
  base=rng.uniform(10000,250000); trend=rng.uniform(-0.09,0.13)
  history=[base]
  for step in range(3):
   history.append(max(base*0.2,history[-1]*(1+trend)+rng.gauss(0,base*0.035)))
  mean=sum(history[:3])/3
  rows.append(dict(latestRatio=history[2]/mean,previousRatio=history[1]/mean,nextRatio=history[3]/mean))
 with (root/f'forecast-{split}.csv').open('w',newline='') as f:
  writer=csv.DictWriter(f,fieldnames=['latestRatio','previousRatio','nextRatio']);writer.writeheader();writer.writerows(rows)
 (root/f'forecast-{split}.json').write_text(json.dumps(rows,indent=2))
print('Prepared 180/36/60 category examples and 1600/320/320 simulated monthly windows.')
